<script setup>
import {useModalDraft} from '../../composables/useModalDraft'
import {reactive,watch,toRef} from 'vue'
import AdminModal from './AdminModal.vue'
import DomainFields from './DomainFields.vue'
import RemotePicker from './catalog/RemotePicker.vue'
import ApiFeedback from './catalog/ApiFeedback.vue'
import {useAuthStore} from '../../stores/auth'
import {useApiMutation} from '../../composables/useApiState'
import {promotionsApi} from '../../api/promotions.api'
import {branchesApi} from '../../api/branches.api'
import {productsApi} from '../../api/products.api'
import {categoriesApi} from '../../api/categories.api'
import {utcInput,utcPayload} from '../../utils/formDates'
const props=defineProps({open:Boolean,record:Object}),emit=defineEmits(['update:open','saved']),auth=useAuthStore(),form=reactive({branches:[],products:[],categories:[]}),mutation=useApiMutation()
const options=values=>values.map(([value,label])=>({value,label}))
const sections=[{title:'معلومات العرض',keys:['name','slug','description']},{title:'الخصم ونطاق التطبيق',keys:['type','application_type','discount_type','discount_value','maximum_discount','minimum_subtotal']},{title:'المدة وحدود الاستخدام',keys:['starts_at','ends_at','usage_limit','usage_limit_per_user']},{title:'الحالة والأولوية',keys:['priority','is_active','is_stackable']}]
const fields=[{key:'name',label:'اسم العرض',required:true,max:180},{key:'slug',label:'الرابط المختصر (اختياري)',max:180,pattern:'[a-z0-9]+(?:-[a-z0-9]+)*'},{key:'description',label:'الوصف',type:'textarea',max:5000},{key:'type',label:'نوع العرض',type:'select',options:options([['automatic','تلقائي'],['coupon','كوبون']])},{key:'application_type',label:'نطاق الخصم',type:'select',options:options([['cart','السلة'],['product','منتجات'],['category','أقسام']])},{key:'discount_type',label:'نوع الخصم',type:'select',options:options([['percentage','نسبة مئوية'],['fixed','مبلغ ثابت'],['fixed_price','سعر خاص للمنتج أو القسم']])},{key:'discount_value',label:'قيمة الخصم',required:true,type:'number',min:0,step:'.01'},{key:'maximum_discount',label:'الحد الأقصى للخصم (اختياري)',type:'number',min:0,step:'.01'},{key:'minimum_subtotal',label:'الحد الأدنى للمنتجات',type:'number',min:0,step:'.01'},{key:'starts_at',label:'البداية UTC',type:'datetime-local',step:1},{key:'ends_at',label:'النهاية UTC',type:'datetime-local',step:1},{key:'priority',label:'الأولوية',type:'number',min:0,max:4294967295,step:1},{key:'usage_limit',label:'حد الاستخدام الكلي (اختياري)',type:'number',min:1,max:4294967295,step:1},{key:'usage_limit_per_user',label:'حد الاستخدام لكل مستخدم (اختياري)',type:'number',min:1,max:4294967295,step:1},{key:'is_active',label:'مفعّل',type:'checkbox'},{key:'is_stackable',label:'يسمح بالجمع وفق قواعد الخادم',type:'checkbox'}]
watch(()=>props.open,open=>{if(open){const r=props.record;Object.assign(form,{name:r?.name||'',slug:r?.slug||'',description:r?.description||'',type:r?.type||'automatic',application_type:r?.application_type||'cart',discount_type:r?.discount?.type||'percentage',discount_value:r?.discount?.value||'',maximum_discount:r?.discount?.maximum??'',minimum_subtotal:r?.minimum_subtotal||'0',starts_at:utcInput(r?.starts_at),ends_at:utcInput(r?.ends_at),is_active:r?.is_active??true,is_stackable:r?.is_stackable??false,priority:r?.priority||0,usage_limit:r?.limits?.usage_limit??'',usage_limit_per_user:r?.limits?.usage_limit_per_user??'',branches:[...(r?.branches||[])],products:[...(r?.products||[])],categories:[...(r?.categories||[])]});mutation.error.value=null}})
function select(key,item,checked){form[key]=checked?[...form[key].filter(r=>r.id!==item.id),item]:form[key].filter(r=>r.id!==item.id)}
async function save(){const payload=Object.fromEntries(fields.map(f=>[f.key,form[f.key]]));for(const key of ['slug','description','maximum_discount','usage_limit','usage_limit_per_user'])payload[key]=payload[key]===''?null:payload[key];for(const key of ['starts_at','ends_at'])payload[key]=utcPayload(form[key],props.record?.[key]);for(const key of ['branches','products','categories'])payload[key]=form[key].map(r=>r.id);if(form.application_type!=='product')payload.products=[];if(form.application_type!=='category')payload.categories=[];const result=await mutation.run(()=>props.record?promotionsApi.update(props.record.id,payload):promotionsApi.create(payload));if(result.ok){emit('update:open',false);emit('saved',result.data)}}
const beforeClose=useModalDraft(toRef(props,'open'),form,mutation.busy)
</script>
<template><AdminModal size="large" :before-close="beforeClose" :open="open" :title="record?'تعديل العرض':'إضافة عرض'" :busy="mutation.busy.value" @update:open="emit('update:open',$event)" @submit="save"><DomainFields :sections="sections" :fields="fields" :form="form" :errors="mutation.error.value?.errors" :disabled="mutation.busy.value"/><template v-for="(api,key) in {branches:branchesApi,products:productsApi,categories:categoriesApi}" :key="key"><div v-if="key==='branches'||form.application_type===(key==='products'?'product':'category')"><h3>{{ key==='branches'?'الفروع (بدون تحديد = كل الفروع)':key==='products'?'المنتجات المستهدفة':'الأقسام المستهدفة' }}</h3><div class="catalog-tags"><span v-for="item in form[key]" :key="item.id" class="badge">{{ item.name }} <button type="button" :disabled="mutation.busy.value" :aria-label="'إزالة '+item.name" @click="select(key,item,false)">×</button></span></div><RemotePicker v-if="open&&auth.can(key==='branches'?'branches.view':key==='products'?'products.view':'categories.view')" :api="api" multiple :exclude="form[key]?.map(r=>r.id)||[]" :disabled="mutation.busy.value" label="بحث وإضافة" @select="(item,checked)=>select(key,item,checked)"/><p v-else-if="open" class="muted">قائمة الأهداف تتطلب صلاحية عرض {{ key==='branches'?'الفروع':key==='products'?'المنتجات':'الأقسام' }}.</p></div></template><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/><p class="form-note">التواريخ بتوقيت UTC. الأهلية والخصم النهائي يحددهما الخادم.</p><button class="button" :disabled="mutation.busy.value">حفظ العرض</button></AdminModal></template>
